    SourceTarget = apps.get_model('sources', 'SourceTarget')
    CollectionTask = apps.get_model('collection', 'CollectionTask')
    CollectionTargetState = apps.get_model('collection', 'CollectionTargetState')
    CollectionSourceLease = apps.get_model('collection', 'CollectionSourceLease')
